using System;
using System.Collections.Generic;

class CodeForge {
    public static int Repeats(List<int> nums) {
        int n = 0;
        // 1, 2 ... n times 0, 1 times 
        var uniqueCounts = nums.GroupBy(x => x)
            .Select(x => new { Element = x.Key, Count = x.Count() })
            .Where(x => x.Count == 1) // Check for numbers appearing only once.
            .Select(x => new { Element = x.Element, Count = x.Element * n }); // Multiply by n (1 for this problem, 2 for the next).

        foreach (var item in uniqueCounts) {
            n += item.Element;
        }

        return n;
    }
}
